"""Funcoes de packages."""


def package_share(part, whole):
    """Percentual de part em whole, com uma casa decimal."""
    if whole == 0:
        return 0.0
    return round(100 * part / whole, 1)


def newest_package(values):
    """Ultimo package da lista ou None."""
    if not values:
        return None
    return values[-1]


def countdown_packages(n):
    """Lista n, n-1, ..., 1 (vazia quando n e zero)."""
    if n < 0:
        return []
    return [n] + countdown_packages(n - 1)

