def employee_clock(seconds):
    """Formata uma duracao de employee em segundos como HH:MM."""
    hours = seconds // 3600
    minutes = seconds // 60
    return f"{hours:02d}:{minutes:02d}"


def employee_label(number):
    """Rotulo com tres digitos para um employee."""
    return "employee-" + str(number).zfill(3)


def clamp_salary(value, low, high):
    """Limita salary ao intervalo [low, high]."""
    return max(low, min(high, value))

