def clamp_minutes(value, low, high):
    """Limita minutes ao intervalo [low, high]."""
    return max(low, min(high, value))


def first_lesson(values):
    """Primeiro lesson ou None quando nao ha nenhum."""
    return values[0] if values else None


def effective_minutes(value, default):
    """Usa o padrao so quando minutes e None; zero e um valor valido."""
    return value or default

